import React from 'react';
import CaseVisual, { isArsenalCase } from './CaseVisual';
import ImageWithFallback from './ImageWithFallback';
import { resolveCaseImage } from '../utils/caseAssets';
import './CaseOpeningSplashUnified.css';
import rifleSplash from '../assets/cases/rifle_arsenal_splash.png';
import sniperSplash from '../assets/cases/sniper_arsenal_splash.png';
import pistolSplash from '../assets/cases/pistol_arsenal_splash.png';
import knifeSplash from '../assets/cases/arsenal_splash_knives.png';
import glovesSplash from '../assets/cases/arsenal_splash_gloves.png';

const arsenalSplash = (name='') => {
  const n=String(name).toLowerCase();
  if(n.includes('rifle arsenal')) return rifleSplash;
  if(n.includes('knife arsenal') || n.includes('knives arsenal')) return knifeSplash;
  if(n.includes('gloves arsenal') || n.includes('glove arsenal')) return glovesSplash;
  if(n.includes('pistol arsenal')) return pistolSplash;
  if(n.includes('sniper arsenal') || n.includes('awp arsenal')) return sniperSplash;
  return null;
};

const tone = (name='') => {
  const n=String(name).toLowerCase();
  if(n.includes('rifle')) return '#7f3142';
  if(n.includes('sniper')||n.includes('awp')) return '#2e6688';
  if(n.includes('pistol')) return '#866226';
  if(n.includes('knife')) return '#8e6a2e';
  if(n.includes('glove')) return '#315f78';
  return '#58697a';
};

export default function CaseOpeningSplashUnified({caseData}){
  const accent=tone(caseData?.name);
  const arsenalArt=arsenalSplash(caseData?.name);
  return <div className="wc61-splash" style={{'--wc61-accent':accent}} data-splash-version="63" role="dialog" aria-label={`Ouverture de ${caseData?.name||'caisse'}`}>
    <div className="wc61-backdrop"/>
    <div className="wc61-card">
      <div className="wc61-kicker">WELLCASE / OUVERTURE SÉCURISÉE</div>
      <h1>{caseData?.name||'WELLCASE'}</h1>
      <div className="wc61-stage">
        {isArsenalCase(caseData?.name) ? (
          arsenalArt ? (
            <div className="wc61-arsenal-splash-art">
              <img src={arsenalArt} alt={caseData?.name || 'Arsenal case'} />
            </div>
          ) : (
            <CaseVisual caseData={caseData} large splash />
          )
        ) : (
          <div className="wc61-case-art">
            <ImageWithFallback
              src={resolveCaseImage(caseData)}
              alt={caseData?.name || 'WELLCASE'}
              className="wc61-case-art-image"
            />
          </div>
        )}
      </div>
      <div className="wc61-status"><span/>DROP SÉCURISÉ</div>
      <div className="wc61-progress"><i/></div>
    </div>
  </div>;
}
